    <script>
        document.addEventListener('turbo:load',()=>{
            const panel=document.getElementById('inventory-panel-single'), asset=panel?.querySelector('#single-asset');
            if(panel?.dataset.staticForm==='1')return;
            if(!panel||!asset||asset.dataset.identitySync==='1')return;
            asset.dataset.identitySync='1';
            let last='';
            const sync=()=>{
                const value=asset.tomselect?asset.tomselect.getValue():asset.value;
                if(!value){last='';return;} if(value===last)return;
                const option=asset.querySelector(`option[value="${CSS.escape(String(value))}"]`);
                if(!option)return;
                last=value;
                [['single-code','code'],['single-name','name'],['single-address','address']].forEach(([id,key])=>{const field=panel.querySelector('#'+id);if(field)field.value=option.dataset[key]||'';});
            };
            setInterval(sync,250);sync();
        });
    </script>
