    <script>
        document.addEventListener('turbo:load',()=>{
            const panel=document.getElementById('inventory-panel-single');
            if(!panel||panel.dataset.staticForm==='1')return;
            ['single-code','single-name'].forEach(id=>{const field=panel.querySelector('#'+id);if(field)field.closest('label')?.remove()||field.remove();});
            const address=panel.querySelector('#single-address');if(address){address.readOnly=true;address.classList.add('bg-slate-50');address.title='Tự động lấy theo vật tư đã chọn';}
            const asset=panel.querySelector('#single-asset');
            const syncIdentity=()=>{const option=asset?.selectedOptions?.[0];if(!option||!option.value)return;[['single-code','code'],['single-name','name'],['single-address','address']].forEach(([id,key])=>{const field=panel.querySelector('#'+id);if(field)field.value=option.dataset[key]||'';});};
            asset?.addEventListener('change',syncIdentity);
            setTimeout(()=>{asset?.tomselect?.on('change',syncIdentity);syncIdentity();},250);
        });
    </script>
