<script>
(()=>{const init=()=>{const rows=document.getElementById('inventory-bulk-rows');if(!rows||rows.dataset.gradeBound==='1')return;rows.dataset.gradeBound='1';const sync=()=>rows.querySelectorAll('select[name$="[grade]"]').forEach(select=>{if(select.dataset.gradeSynced==='1')return;const value=select.value||'1';select.className=select.className.replace('w-28','w-36');select.innerHTML='<option value="1">Cấp 1 — Rất bền</option><option value="2">Cấp 2 — Bền</option><option value="3">Cấp 3 — Khá bền</option><option value="4">Cấp 4 — Trung bình</option><option value="5">Cấp 5 — Kém bền</option>';select.value=value;select.dataset.gradeSynced='1'});sync();new MutationObserver(sync).observe(rows,{childList:true,subtree:true});};document.addEventListener('DOMContentLoaded',init);document.addEventListener('turbo:load',init);if(document.readyState!=='loading')init();})();
</script>
<script>
(()=>{const removeUnusedLocations=()=>{const bulk=document.getElementById('inventory-panel-bulk');if(!bulk)return;['building_id','classroom_id','holding_unit_id'].forEach(name=>bulk.querySelectorAll(`[name="${name}"]`).forEach(field=>{const target=field.closest('label')||field.closest('.ts-wrapper')||field;const sibling=field.nextElementSibling?.classList.contains('ts-wrapper')?field.nextElementSibling:null;sibling?.remove();target.remove()}));bulk.querySelectorAll('label').forEach(label=>{const text=label.textContent?.trim()||'';if(text.startsWith('Tòa nhà')||text.startsWith('Phòng')||text.startsWith('Đơn vị quản lý'))label.remove()});};document.addEventListener('DOMContentLoaded',removeUnusedLocations);document.addEventListener('turbo:load',removeUnusedLocations);setTimeout(removeUnusedLocations,500);setTimeout(removeUnusedLocations,1500);})();
